@if($paginator->hasPages())<div class="page-list">@if($paginator->onFirstPage())<span class="page-number page-step disabled">Trước</span>@else<a class="page-number page-step" href="{{ $paginator->previousPageUrl() }}">Trước</a>@endif @foreach($elements as $element) @if(is_array($element)) @foreach($element as $page=>$url)<a class="page-number {{ $page===$paginator->currentPage() ? 'active' : '' }}" href="{{ $url }}" @if($page===$paginator->currentPage()) aria-current="page" @endif>{{ $page }}</a>@endforeach @else<span class="page-number disabled">…</span>@endif @endforeach @if($paginator->hasMorePages())<a class="page-number page-step" href="{{ $paginator->nextPageUrl() }}">Tiếp</a>@else<span class="page-number page-step disabled">Tiếp</span>@endif</div>@endif